import React, { useState, useEffect } from 'react';
import { Link, useParams } from 'react-router-dom';
import './Forum.css';
import ThreadList from '../Thread/ThreadList';

const ForumDetail = () => {
    const { id } = useParams();
    const [forum, setForum] = useState(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        // Charger le fichier JSON basé sur l'ID du forum
        fetch(`/data/forumDetail-${id}.json`)
            .then(response => response.json())
            .then(data => {
                setForum(data);
                setLoading(false);
            })
            .catch(error => {
                console.error('Error fetching forum data:', error);
                setLoading(false);
            });
    }, [id]);

    if (loading) {
        return <p>Loading...</p>;
    }

    if (!forum) {
        return <p>Forum not found</p>;
    }

    const { subForums = [], breadcrumb = [] } = forum;

    return (
        <div className="forum-detail">
            {/* Fil d'Ariane */}
            <nav className="breadcrumb">
                {breadcrumb.map((crumb, index) => (
                    <span key={index}>
                        <Link to={crumb.url}>{crumb.name}</Link>
                        {index < breadcrumb.length - 1 && " > "}
                    </span>
                ))}
            </nav>

            <h2>{forum.name}</h2>
            <p>{forum.description}</p>

            {subForums.length > 0 && (
                <div className="subforums">
                    <h3>Subforums</h3>
                    <ul>
                        {subForums.map(subForum => (
                            <li key={subForum.id}>
                                <h4>
                                    <Link to={`/subforum/${subForum.id}`}>{subForum.name}</Link>
                                </h4>
                                <p>{subForum.description}</p>
                                <div className="last-thread">
                                    <p><strong>Last thread:</strong> {subForum.lastThread?.title}</p>
                                    <p><em>by {subForum.lastThread?.author} on {subForum.lastThread?.date}</em></p>
                                    <p>
                                        <Link to={`/thread/${subForum.lastThread?.threadId}`}>
                                            View last thread
                                        </Link>
                                    </p>
                                </div>
                            </li>
                        ))}
                    </ul>
                </div>
            )}

            <div className="threads">
                <h3>Threads</h3>
                <ThreadList forumId={forum.id} />
            </div>
        </div>
    );
};

export default ForumDetail;
